{
  "name": "ProFlex PCR热循环仪",
  "name_en": "ProFlex PCR Thermocycler",
  "manufacturer": "Thermo Fisher Scientific",
  "description": "用于PCR热循环实验的热循环仪，可控制反应模块与热盖温度、运行或中止扩增程序，并查询运行状态、步骤、时间和日志等信息。",
  "description_en": "A thermocycler for PCR workflows that controls block and heated-lid temperatures, runs or aborts amplification protocols, and reports run status, steps, timing, and log information.",
  "tag_hints": [
    "PCR thermocycling",
    "ProFlex thermocycler",
    "block temperature control",
    "heated lid control",
    "PCR protocol execution",
    "run status monitoring",
    "multi-block thermal cycling"
  ],
  "actions": [
    {
      "action_name": "auto-abort_run",
      "description": "中止指定模块上的运行程序。",
      "description_en": "Abort the running program on the specified block."
    },
    {
      "action_name": "auto-block_ramp_single_temp",
      "description": "按设定升降温速率将指定模块升降到单一目标温度。",
      "description_en": "Ramp the specified block to a single target temperature at the specified rate."
    },
    {
      "action_name": "auto-buzzer_off",
      "description": "关闭设备蜂鸣器。",
      "description_en": "Turn off the instrument buzzer."
    },
    {
      "action_name": "auto-buzzer_on",
      "description": "打开设备蜂鸣器。",
      "description_en": "Turn on the instrument buzzer."
    },
    {
      "action_name": "auto-check_run_exists",
      "description": "检查指定名称的运行记录或程序是否存在。",
      "description_en": "Check whether a run or saved entry with the specified name exists."
    },
    {
      "action_name": "auto-continue_run",
      "description": "继续指定模块上的运行程序。",
      "description_en": "Continue the run on the specified block."
    },
    {
      "action_name": "auto-create_run",
      "description": "在设备上创建一个指定名称的运行记录。",
      "description_en": "Create a named run entry on the instrument."
    },
    {
      "action_name": "auto-deactivate_block",
      "description": "关闭指定模块的温控。",
      "description_en": "Deactivate temperature control for the specified block."
    },
    {
      "action_name": "auto-deactivate_lid",
      "description": "关闭指定模块热盖的温控。",
      "description_en": "Deactivate heated-lid control for the specified block."
    },
    {
      "action_name": "auto-is_block_running",
      "description": "获取指定模块是否正在运行。",
      "description_en": "Get whether the specified block is currently running."
    },
    {
      "action_name": "auto-power_off",
      "description": "关闭设备电源。",
      "description_en": "Power off the instrument."
    },
    {
      "action_name": "auto-power_on",
      "description": "打开设备电源。",
      "description_en": "Power on the instrument."
    },
    {
      "action_name": "auto-run_protocol",
      "description": "在指定模块上运行PCR协议，包括热盖设置、体积和运行模式等参数。",
      "description_en": "Run a PCR protocol on the specified block, including lid settings, volume, and run mode parameters."
    },
    {
      "action_name": "auto-send_command",
      "description": "向设备发送底层原始命令并读取响应。",
      "description_en": "Send a low-level raw command to the instrument and read the response."
    },
    {
      "action_name": "auto-send_morse_code",
      "description": "通过设备蜂鸣器发送摩尔斯码提示。",
      "description_en": "Send Morse code output through the instrument buzzer."
    },
    {
      "action_name": "auto-set_block_idle_temp",
      "description": "设置指定模块的空闲温度。",
      "description_en": "Set the idle temperature for the specified block."
    },
    {
      "action_name": "auto-set_block_temperature",
      "description": "设置指定模块的温度，可带升降温速率。",
      "description_en": "Set the temperature of the specified block, optionally with a ramp rate."
    },
    {
      "action_name": "auto-set_cover_idle_temp",
      "description": "设置指定模块热盖的空闲温度。",
      "description_en": "Set the idle temperature of the heated lid for the specified block."
    },
    {
      "action_name": "auto-set_lid_temperature",
      "description": "设置指定模块热盖温度。",
      "description_en": "Set the heated-lid temperature for the specified block."
    },
    {
      "action_name": "auto-set_nickname",
      "description": "设置设备昵称。",
      "description_en": "Set the instrument nickname."
    },
    {
      "action_name": "auto-setup",
      "description": "初始化设备并设置模块与热盖的空闲温度。",
      "description_en": "Initialize the instrument and set idle temperatures for blocks and heated lids."
    },
    {
      "action_name": "auto-stop",
      "description": "停止当前热循环操作。",
      "description_en": "Stop the current thermocycling operation."
    },
    {
      "action_name": "auto-num_blocks",
      "description": "获取温控模块数量。",
      "description_en": "Get the number of thermal blocks."
    },
    {
      "action_name": "auto-get_block_current_temperature",
      "description": "获取指定模块当前温度。",
      "description_en": "Get the current temperature of the specified block."
    },
    {
      "action_name": "auto-get_sample_temps",
      "description": "获取指定模块样品温度。",
      "description_en": "Get the sample temperatures for the specified block."
    },
    {
      "action_name": "auto-get_nickname",
      "description": "获取设备昵称。",
      "description_en": "Get the instrument nickname."
    },
    {
      "action_name": "auto-get_log_by_runname",
      "description": "获取指定运行名称对应的日志内容。",
      "description_en": "Get the log content associated with the specified run name."
    },
    {
      "action_name": "auto-get_elapsed_run_time_from_log",
      "description": "获取从运行日志解析出的已运行时间。",
      "description_en": "Get the elapsed run time parsed from a run log."
    },
    {
      "action_name": "auto-get_block_id",
      "description": "获取模块标识。",
      "description_en": "Get the block identifier."
    },
    {
      "action_name": "auto-get_block_presence",
      "description": "获取模块是否存在。",
      "description_en": "Get whether a block is present."
    },
    {
      "action_name": "auto-get_run_name",
      "description": "获取指定模块当前运行名称。",
      "description_en": "Get the current run name for the specified block."
    },
    {
      "action_name": "auto-get_estimated_run_time",
      "description": "获取指定模块预计运行时间。",
      "description_en": "Get the estimated run time for the specified block."
    },
    {
      "action_name": "auto-get_elapsed_run_time",
      "description": "获取指定模块已运行时间。",
      "description_en": "Get the elapsed run time for the specified block."
    },
    {
      "action_name": "auto-get_remaining_run_time",
      "description": "获取指定模块剩余运行时间。",
      "description_en": "Get the remaining run time for the specified block."
    },
    {
      "action_name": "auto-get_error",
      "description": "获取指定模块错误状态或错误信息。",
      "description_en": "Get the error state or error information for the specified block."
    },
    {
      "action_name": "auto-get_run_info",
      "description": "获取指定协议在指定模块上的运行信息。",
      "description_en": "Get run information for the specified protocol on the specified block."
    },
    {
      "action_name": "auto-get_lid_current_temperature",
      "description": "获取热盖当前温度。",
      "description_en": "Get the current heated-lid temperature."
    },
    {
      "action_name": "auto-get_block_status",
      "description": "获取模块状态。",
      "description_en": "Get the block status."
    },
    {
      "action_name": "auto-get_current_cycle_index",
      "description": "获取当前循环序号。",
      "description_en": "Get the current cycle index."
    },
    {
      "action_name": "auto-get_current_step_index",
      "description": "获取当前步骤序号。",
      "description_en": "Get the current step index."
    },
    {
      "action_name": "auto-get_hold_time",
      "description": "获取保持时间。",
      "description_en": "Get the hold time."
    },
    {
      "action_name": "auto-get_lid_open",
      "description": "获取热盖是否打开。",
      "description_en": "Get whether the lid is open."
    },
    {
      "action_name": "auto-get_lid_status",
      "description": "获取热盖状态。",
      "description_en": "Get the lid status."
    },
    {
      "action_name": "auto-get_lid_target_temperature",
      "description": "获取热盖目标温度。",
      "description_en": "Get the heated-lid target temperature."
    },
    {
      "action_name": "auto-get_total_cycle_count",
      "description": "获取总循环次数。",
      "description_en": "Get the total cycle count."
    },
    {
      "action_name": "auto-get_total_step_count",
      "description": "获取总步骤数。",
      "description_en": "Get the total step count."
    },
    {
      "action_name": "auto-get_block_target_temperature",
      "description": "获取模块目标温度。",
      "description_en": "Get the block target temperature."
    }
  ]
}

